with parsed as (select id, plan, currency, discounts, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, slice(tier_limits, 1, 2) as first_two_limits, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices from price_tiers) select currency, sort_array(collect_set(plan)) as plan_list, count(*) filter (where currency = 'USD') as usd_rows, count(*) filter (where currency = 'THB') as thb_rows, count(*) as event_count, size(collect_set(plan)) as num_plans, count(*) filter (where currency = 'THB') as thb_rows_2 from parsed group by currency order by event_count desc nulls first;
